import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def real_samples(ctx):
    values = torch.randn(4, generator=ctx.rng.torch)
    return {"inputs": synth.Tensor(values)}
dataset = synth.Spec("r1-real-samples", generator=real_samples, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class Critic(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=1)
    def forward(self, inputs):
        real_samples = inputs.requires_grad_()
        scores = self.network(real_samples).reshape(-1)
        return {"real_samples": real_samples, "scores": scores}
trainer = Trainer(Critic(), train, recipe="structured-objective", recipe_config={"loss": "r1-penalty", "loss_kwargs": {"gamma": 10.0}, "bindings": {"logits_or_prediction": {"output": "real_samples"}, "targets": {"output": "scores"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
